    41	/**
    42	 * Evaluator which uses reflection to get path from an object.
    43	 * Uses expression visitor API to interpret the expression.
    44	 */
    45	class ExpressionInterpreter implements Function<Object, Object> {
    46	
    47	  /**
    48	   * Sentinel used for Three-Valued Logic (3VL): true / false / unknown
    49	   */
    50	  private static final Object UNKNOWN = new Object() {
    51	    @Override
    52	    public String toString() {
    53	      return "UNKNOWN";
    54	    }
    55	  };
    56	
    57	  private final Expression expression;
    58	
    59	  private ExpressionInterpreter(Expression expression) {
    60	    this.expression = Objects.requireNonNull(expression, "expression");
    61	  }
    62	
    63	  static ExpressionInterpreter of(Expression expression) {
    64	    return new ExpressionInterpreter(expression);
    65	  }
    66	
    67	  /**
    68	   * Predicate to check that current expression with given parameter evaluates to {@code true}
    69	   */
    70	  Predicate<Object> asPredicate() {
    71	    return value -> Boolean.TRUE.equals(apply(value));
    72	  }
    73	
    74	  @Override
    75	  public Object apply(Object instance) {
    76	    return expression.accept(new LocalVisitor(instance));
    77	  }
    78	
    79	  private static class LocalVisitor implements ExpressionVisitor<Object> {
    80	
    81	    private static final PathExtractor EXTRACTOR = new ReflectionExtractor();
    82	    private final Object instance;
    83	
    84	    private LocalVisitor(Object instance) {
    85	      this.instance = instance;
    86	    }
    87	
    88	    @Override
    89	    public Object visit(Call call) {
    90	      final Operator op = call.operator();
    91	      final List<Expression> args = call.arguments();
    92	
    93	
    94	      if (op == Operators.NOT) {
    95	        Preconditions.checkArgument(args.size() == 1, "Size should be 1 for %s but was %s", op, args.size());
    96	        final Object value = args.get(0).accept(this);
    97	
    98	        if (value == UNKNOWN) {
    99	          return UNKNOWN;
   100	        }
   101	
   102	        if (value instanceof Boolean) {
   103	          return !(Boolean) value;
   104	        }
   105	
   106	        throw new UnsupportedOperationException(String.format("Expected boolean for op %s but got %s", op, value.getClass().getName()));
   107	      }
   108	
   109	      if (op == IterableOperators.IS_EMPTY || op == IterableOperators.NOT_EMPTY) {
   110	        Preconditions.checkArgument(args.size() == 1, "Size should be 1 for %s but was %s", op, args.size());
   111	        final Object value = args.get(0).accept(this);
   112	        if (value == UNKNOWN) {
   113	          return UNKNOWN;
   114	        }
   115	
   116	        Preconditions.checkArgument(value instanceof Iterable, "%s not iterable", value.getClass().getName());
   117	        final boolean empty = Iterables.isEmpty((Iterable<?>) value);
   118	        return (op == IterableOperators.IS_EMPTY) == empty;
   119	      }
   120	
   121	      if (op == OptionalOperators.IS_ABSENT || op == OptionalOperators.IS_PRESENT) {
   122	        Preconditions.checkArgument(args.size() == 1, "Size should be 1 for %s but was %s", op, args.size());
   123	        final Object left = args.get(0).accept(this);
   124	
   125	        if (left == UNKNOWN) {
   126	         return (op == OptionalOperators.IS_ABSENT);
   127	        }
   128	
   129	        return (op == OptionalOperators.IS_ABSENT) ? Objects.isNull(left) : Objects.nonNull(left);
   130	      }
   131	
   132	      if (op == StringOperators.TO_UPPER_CASE || op == StringOperators.TO_LOWER_CASE) {
   133	        Preconditions.checkArgument(args.size() == 1, "Size should be 1 but was %s", args.size());
   134	        Object value = args.get(0).accept(this);
   135	        if (value == null || value == UNKNOWN) {
   136	          return UNKNOWN;
   137	        }
   138	
   139	        Preconditions.checkArgument(value instanceof CharSequence, "Expected %s got %s", CharSequence.class.getSimpleName(), value.getClass().getName());
   140	        return op == StringOperators.TO_UPPER_CASE ? value.toString().toUpperCase() : value.toString().toLowerCase();
   141	      }
   142	
   143	      if (op == Operators.AND || op == Operators.OR) {
   144	        Preconditions.checkArgument(!args.isEmpty(), "empty args for %s", op);
   145	        final boolean shortCircuit = op == Operators.OR;
   146	        boolean prev = !shortCircuit;
   147	        for (Expression exp:args) {
   148	          final Object result = exp.accept(this);
   149	          if (result == null || result == UNKNOWN) {
   150	            return UNKNOWN;
   151	          } else if (prev == shortCircuit || Objects.equals(shortCircuit, result)) {
   152	            return shortCircuit;
   153	          } else {
   154	            // continue evaluating
   155	            prev = (Boolean) result;
   156	          }
   157	        }
   158	
   159	        return prev;
   160	      }
   161	      
   162	      if (op == IterableOperators.ANY) {
   163	        Preconditions.checkArgument(call.arguments().size() == 2, "Expected two arguments for %s got %s", call, call.arguments().size());
   164	        
   165	        final Object left = call.arguments().get(0).accept(this);
   166	        Preconditions.checkArgument(left instanceof Iterable, "%s is not iterable", left);
   167	        @SuppressWarnings("unchecked")
   168	        final Iterable<Object> leftIterable = (Iterable<Object>) left;
   169	        Preconditions.checkArgument(call.arguments().get(1) instanceof Call, "%s is not a call", call.arguments().get(1));
   170	        final Call rightCall = (Call) call.arguments().get(1);
   171	
   172	        final Stream<Object> stream = StreamSupport.stream(leftIterable.spliterator(), false);
   173	        return stream.anyMatch(r -> ExpressionInterpreter.of(rightCall).asPredicate().test(r));
   174	      }
   175	
   176	      if (op.arity() == Operator.Arity.BINARY) {
   177	        Preconditions.checkArgument(call.arguments().size() == 2, "Expected two arguments for %s got %s", call, call.arguments().size());
   178	        final Object left = call.arguments().get(0).accept(this);
   179	        if (left == UNKNOWN) {
   180	          return UNKNOWN;
   181	        }
   182	
   183	        final Object right = call.arguments().get(1).accept(this);
   184	        if (right == UNKNOWN) {
   185	          return UNKNOWN;
   186	        }
   187	
   188	        return binaryCall(call, left, right);
   189	      }
   190	
   191	      throw new UnsupportedOperationException("Don't know how to handle " + op);
   192	    }
   193	
   194	    private static Object binaryCall(Call call, Object left, Object right) {
   195	      Preconditions.checkArgument(call.operator().arity() == Operator.Arity.BINARY, "Expected binary call got %s", call);
   196	      final Operator op = call.operator();
   197	
   198	      if (op == Operators.EQUAL || op == Operators.NOT_EQUAL) {
   199	        final boolean equals = Objects.equals(left, right);
   200	        return (op == Operators.EQUAL) == equals;
   201	      }
   202	
   203	      if (op == Operators.IN || op == Operators.NOT_IN) {
   204	        Preconditions.checkArgument(right instanceof Iterable, "%s is not iterable", left.getClass());
   205	        @SuppressWarnings("unchecked")
   206	        final Iterable<Object> rightValue = (Iterable<Object>) right;
   207	        final Stream<Object> stream = StreamSupport.stream(rightValue.spliterator(), false);
   208	        return op == Operators.IN ? stream.anyMatch(r -> Objects.equals(left, r)) : stream.noneMatch(r -> Objects.equals(left, r));
   209	      }
   210	
   211	      if (op == IterableOperators.HAS_SIZE) {
   212	        Preconditions.checkArgument(left instanceof Iterable, "%s is not iterable", left);
   213	        Preconditions.checkArgument(right instanceof Number, "%s is not a number", left);
   214	        final Iterable<?> iter = (Iterable<?>) left;
   215	        final int size = ((Number) right).intValue();
   216	        return Iterables.size(iter) == size;
   217	      }
   218	
   219	      if (op == IterableOperators.CONTAINS) {
   220	        Preconditions.checkArgument(left instanceof Iterable, "%s is not iterable", left);
   221	        return Iterables.contains((Iterable<?>) left, right);
   222	      }
   223	
   224	      // comparables
   225	      if (ComparableOperators.isComparable(call.operator())) {
   226	        Preconditions.checkArgument(left instanceof Comparable, "%s is not comparable", left);
   227	        @SuppressWarnings("unchecked")
   228	        final Comparable<Object> leftComparable = (Comparable<Object>) left;
   229	
   230	        Preconditions.checkArgument(right instanceof Comparable, "%s is not comparable", right);
   231	        @SuppressWarnings("unchecked")
   232	        final Comparable<Object> rightComparable = (Comparable<Object>) right;
   233	
   234	        final int compare = leftComparable.compareTo(rightComparable);
   235	
   236	        if (op == ComparableOperators.GREATER_THAN) {
   237	          return compare > 0;
   238	        } else if (op == ComparableOperators.GREATER_THAN_OR_EQUAL) {
   239	          return compare >= 0;
   240	        } else if (op == ComparableOperators.LESS_THAN) {
   241	          return compare < 0;
   242	        } else if (op == ComparableOperators.LESS_THAN_OR_EQUAL) {
   243	          return compare <= 0;
   244	        }
   245	      }
   246	
   247	      if (op == StringOperators.HAS_LENGTH) {
   248	        Preconditions.checkArgument(left instanceof CharSequence, "%s is not CharSequence", left);
   249	        Preconditions.checkArgument(right instanceof Number, "%s is not Number", right);
   250	        int length = ((Number) right).intValue();
   251	        return left.toString().length() == length;
   252	      }
   253	
   254	      if (op == StringOperators.MATCHES) {
   255	        Preconditions.checkArgument(left instanceof CharSequence, "%s is not string (or CharSequence)", left);
   256	        Preconditions.checkArgument(right instanceof Pattern, "%s is not regex pattern", right);
   257	        return ((Pattern) right).asPredicate().test(left.toString());
   258	      }
   259	
   260	      if (op == StringOperators.STARTS_WITH || op == StringOperators.ENDS_WITH || op == StringOperators.CONTAINS) {
   261	        Preconditions.checkArgument(left instanceof CharSequence, "%s is not string (or CharSequence)", left);
   262	        Preconditions.checkArgument(right instanceof CharSequence, "%s is not string (or CharSequence)", right);
   263	
   264	        if (op == StringOperators.CONTAINS) {
   265	          return left.toString().contains(right.toString());
   266	        }
   267	
   268	        return op == StringOperators.STARTS_WITH ? left.toString().startsWith(right.toString()) : left.toString().endsWith(right.toString());
   269	      }
   270	
   271	      throw new UnsupportedOperationException("Unsupported binary call " + call);
   272	    }
   273	
   274	    @Override
   275	    public Object visit(Constant constant) {
   276	      return constant.value();
   277	    }
