import org.immutables.check.IterableChecker;
import org.immutables.criteria.backend.Backend;
import org.immutables.criteria.matcher.IterableMatcher;
import org.immutables.criteria.personmodel.CriteriaChecker;
import org.junit.jupiter.api.Test;

import java.util.Arrays;
import java.util.List;
import java.util.function.Supplier;

/**
 * Testing collection element quantifiers.
 */
public abstract class AnyTemplate {

  private final StringHolderRepository repository;
  private final IntegerHolderRepository integers;
  private final StringHolderCriteria string = StringHolderCriteria.stringHolder;
  private final IntegerHolderCriteria integer = IntegerHolderCriteria.integerHolder;
  private final Supplier<ImmutableStringHolder> generator;
  private final Supplier<ImmutableIntegerHolder> integerGenerator;

  protected AnyTemplate(Backend backend) {
    this.repository = new StringHolderRepository(backend);
    this.integers = new IntegerHolderRepository(backend);
    this.generator = TypeHolder.StringHolder.generator();
    this.integerGenerator = TypeHolder.IntegerHolder.generator();
  }

  @Test
  void empty() {
    insert("empty");

    ids(string.array.any().is("a")).isEmpty();
    ids(string.array.all().is("a")).isOf("empty");
    ids(string.array.none().is("a")).isOf("empty");
    ids(string.list.any().is("a")).isEmpty();
    ids(string.list.all().is("a")).isOf("empty");
    ids(string.list.none().is("a")).isOf("empty");
  }

  @Test
  void scalarArrayAndList() {
    insert("all-a", "a", "aa");
    insert("mixed", "a", "b");
    insert("all-b", "b", "bb");

    ids(string.array.any().startsWith("a")).hasContentInAnyOrder("all-a", "mixed");
    ids(string.array.all().startsWith("a")).isOf("all-a");
    ids(string.array.none().startsWith("a")).isOf("all-b");

    ids(string.list.any().endsWith("b")).hasContentInAnyOrder("mixed", "all-b");
    ids(string.list.all().hasLength(1)).isOf("mixed");
    ids(string.list.none().contains("z")).hasContentInAnyOrder("all-a", "mixed", "all-b");
  }

  @Test
  void negativeAndCompound() {
    insert("same", "a", "a");
    insert("different", "a", "b");

    ids(string.array.any().isNot("a")).isOf("different");
    ids(string.array.all().isNot("a")).isEmpty();
    ids(string.array.none().isNot("a")).isOf("same");

    ids(string.array.any().with(v -> v.is("a").and(v.is("b")))).isEmpty();
    ids(string.array.none().with(v -> v.is("a").and(v.is("b"))))
        .hasContentInAnyOrder("same", "different");
    ids(string.array.all().with(v -> v.is("a").or(v.is("b"))))
        .hasContentInAnyOrder("same", "different");
  }

  @Test
  void primitiveArray() {
    integers.insert(integerGenerator.get().withId("positive").withArray(1, 2, 3));
    integers.insert(integerGenerator.get().withId("mixed").withArray(-1, 1));
    integers.insert(integerGenerator.get().withId("empty").withArray());

    integerIds(integer.array.any().greaterThan(0)).hasContentInAnyOrder("positive", "mixed");
    integerIds(integer.array.all().greaterThan(0)).hasContentInAnyOrder("positive", "empty");
    integerIds(integer.array.none().greaterThan(0)).isOf("empty");
  }

  private void insert(String id, String... values) {
    repository.insert(generator.get().withId(id).withArray(values).withList(Arrays.asList(values)));
  }

  private IterableChecker<List<String>, String> ids(StringHolderCriteria criteria) {
    return CriteriaChecker.<TypeHolder.StringHolder>ofReader(repository.find(criteria)).toList(TypeHolder.StringHolder::id);
  }

  private IterableChecker<List<String>, String> integerIds(IntegerHolderCriteria criteria) {
    return CriteriaChecker.<TypeHolder.IntegerHolder>ofReader(integers.find(criteria)).toList(TypeHolder.IntegerHolder::id);
  }
