package org.immutables.criteria.mongo;

import com.google.common.base.Preconditions;
import com.google.common.collect.ImmutableSet;
import com.mongodb.client.model.Filters;
import org.bson.BsonDocument;
import org.bson.BsonInt32;
import org.bson.BsonNull;
import org.bson.BsonType;
import org.bson.BsonValue;
import org.bson.codecs.configuration.CodecRegistry;
import org.bson.conversions.Bson;
import org.immutables.criteria.backend.PathNaming;
import org.immutables.criteria.expression.Call;
import org.immutables.criteria.expression.ComparableOperators;
import org.immutables.criteria.expression.Expression;
import org.immutables.criteria.expression.IterableOperators;
import org.immutables.criteria.expression.Operator;
import org.immutables.criteria.expression.Operators;
import org.immutables.criteria.expression.OptionalOperators;
import org.immutables.criteria.expression.Path;
import org.immutables.criteria.expression.StringOperators;
import org.immutables.criteria.expression.Visitors;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.List;
import java.util.Objects;
import java.util.regex.Pattern;

final class QuantifierFindVisitor {

  private final PathNaming naming;
  private final CodecRegistry codecRegistry;

  QuantifierFindVisitor(PathNaming naming, CodecRegistry codecRegistry) {
    this.naming = Objects.requireNonNull(naming, "naming");
    this.codecRegistry = Objects.requireNonNull(codecRegistry, "codecRegistry");
  }

  Bson filter(Call call) {
    return truth(call).trueCondition;
  }

  private Truth truth(Expression expression) {
    Preconditions.checkArgument(expression instanceof Call, "%s is not a call", expression);
    Call call = (Call) expression;
    Operator operator = call.operator();

    if (operator == Operators.NOT) {
      Truth inner = truth(call.arguments().get(0));
      return new Truth(inner.falseCondition, inner.trueCondition, inner.unknownCondition, inner.scalar);
    }

    if (operator == Operators.AND || operator == Operators.OR) {
      List<Bson> trueConditions = new ArrayList<>();
      List<Bson> falseConditions = new ArrayList<>();
      List<Bson> unknownConditions = new ArrayList<>();
      boolean scalar = true;
      for (Expression argument : call.arguments()) {
        Truth child = truth(argument);
        trueConditions.add(child.trueCondition);
        falseConditions.add(child.falseCondition);
        unknownConditions.add(child.unknownCondition);
        scalar &= child.scalar;
      }

      if (operator == Operators.AND) {
        Bson trueCondition = scalar ? scalarAnd(trueConditions) : Filters.and(trueConditions);
        Bson falseCondition = scalar ? scalarOr(falseConditions) : Filters.or(falseConditions);
        Bson unknownCondition = scalar
            ? new BsonDocument("$eq", BsonNull.VALUE)
            : Filters.and(Filters.nor(falseCondition), Filters.or(unknownConditions));
        return new Truth(trueCondition, falseCondition, unknownCondition, scalar);
      }

      Bson trueCondition = scalar ? scalarOr(trueConditions) : Filters.or(trueConditions);
      Bson falseCondition = scalar ? scalarAnd(falseConditions) : Filters.and(falseConditions);
      Bson unknownCondition = scalar
          ? new BsonDocument("$eq", BsonNull.VALUE)
          : Filters.and(Filters.nor(trueCondition), Filters.or(unknownConditions));
      return new Truth(trueCondition, falseCondition, unknownCondition, scalar);
    }

    if (isQuantifier(operator)) {
      return quantified(call);
    }

    Path path = Visitors.toPath(call.arguments().get(0));
    boolean scalar = path.members().isEmpty();

    if (operator == OptionalOperators.IS_PRESENT || operator == OptionalOperators.IS_ABSENT) {
      Bson present = present(path);
      Bson absent = absent(path);
      return operator == OptionalOperators.IS_PRESENT
          ? new Truth(present, absent, impossible(), scalar)
          : new Truth(absent, present, impossible(), scalar);
    }

    if (operator == IterableOperators.IS_EMPTY || operator == IterableOperators.NOT_EMPTY) {
      Bson known = type(path, BsonType.ARRAY);
      Bson unknown = notType(path, BsonType.ARRAY);
      Bson empty = condition(path, new BsonDocument("$eq", new org.bson.BsonArray()));
      Bson nonEmpty = condition(path, new BsonDocument("$ne", new org.bson.BsonArray()));
      return operator == IterableOperators.IS_EMPTY
          ? new Truth(Filters.and(known, empty), Filters.and(known, nonEmpty), unknown, scalar)
          : new Truth(Filters.and(known, nonEmpty), Filters.and(known, empty), unknown, scalar);
    }

    Preconditions.checkArgument(operator.arity() == Operator.Arity.BINARY, "Unsupported quantified call %s", call);
    Object value = Visitors.toConstant(call.arguments().get(1)).value();
    Bson trueCondition;
    Bson falseCondition;
    Bson unknownCondition = absent(path);

    if (scalar && (operator == Operators.EQUAL || operator == Operators.NOT_EQUAL)) {
      Bson equal = new BsonDocument("$eq", encode(value));
      Bson notEqual = new BsonDocument("$nin", new org.bson.BsonArray(Arrays.asList(encode(value), BsonNull.VALUE)));
      trueCondition = operator == Operators.EQUAL ? equal : notEqual;
      falseCondition = operator == Operators.EQUAL ? notEqual : equal;
    } else if (operator == Operators.EQUAL || operator == Operators.NOT_EQUAL) {
      Bson equal = condition(path, new BsonDocument("$eq", encode(value)));
      Bson notEqual = condition(path, new BsonDocument("$ne", encode(value)));
      trueCondition = operator == Operators.EQUAL ? equal : notEqual;
      falseCondition = operator == Operators.EQUAL ? notEqual : equal;
    } else if (operator == Operators.IN || operator == Operators.NOT_IN) {
      Collection<?> values = ImmutableSet.copyOf(Visitors.toConstant(call.arguments().get(1)).values());
      BsonValue encoded = encode(values);
      Collection<Object> valuesWithNull = new ArrayList<>();
      valuesWithNull.addAll(values);
      valuesWithNull.add(null);
      Bson in = condition(path, new BsonDocument("$in", encoded));
      Bson notIn = condition(path, new BsonDocument("$nin", scalar ? encode(valuesWithNull) : encoded));
      trueCondition = operator == Operators.IN ? in : notIn;
      falseCondition = operator == Operators.IN ? notIn : in;
    } else if (ComparableOperators.isComparable(operator)) {
      String queryOperator = comparisonName(operator);
      String inverseOperator = inverseComparisonName(operator);
      BsonDocument trueComparison = new BsonDocument(queryOperator, encode(value));
      BsonDocument falseComparison = new BsonDocument(inverseOperator, encode(value));
      if (scalar) {
        trueComparison.append("$ne", BsonNull.VALUE);
        falseComparison.append("$ne", BsonNull.VALUE);
      }
      trueCondition = condition(path, trueComparison);
      falseCondition = condition(path, falseComparison);
    } else if (operator == IterableOperators.HAS_SIZE) {
      Bson known = type(path, BsonType.ARRAY);
      unknownCondition = notType(path, BsonType.ARRAY);
      Bson size = condition(path, new BsonDocument("$size", new BsonInt32(((Number) value).intValue())));
