    59	      List<Bson> unknownConditions = new ArrayList<>();
    60	      boolean scalar = true;
    61	      for (Expression argument : call.arguments()) {
    62	        Truth child = truth(argument);
    63	        trueConditions.add(child.trueCondition);
    64	        falseConditions.add(child.falseCondition);
    65	        unknownConditions.add(child.unknownCondition);
